head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL20000";
scwin.conFormObj = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil20000.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb37", attr: "label", fn: function () { return String(dma_company.get("comNm")); } },
        { childId: "__rb38", attr: "label", fn: function () { return String(dma_user.get("corpUsrNm")); } },
        { childId: "__rb39", attr: "label", fn: function () { return String(dma_user.get("email")); } },
        { childId: "__rb40", attr: "label", fn: function () { return String(dma_user.get("telNo")); } },
        { childId: "__rb41", attr: "label", fn: function () { return String(dma_user.get("faxNo")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_spotIsuTrdMktTpCd", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_24", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_29", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "c_when_74_txt", fn: function(){ return (!(String(((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })())) == null ? '' : ((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()))).length === 0) && (dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()) === 'KRW'); } }, { id: "c_otherwise_75", fn: function(){ return (!((!(String(((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })())) == null ? '' : ((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()))).length === 0) && (dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()) === 'KRW'))); } }, { id: "c_when_61", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_62", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_67", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_76", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_81", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "tr_86", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "c_otherwise_89", fn: function(){ return (!(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'))); } }, { id: "c_when_97_txt", fn: function(){ return (!(String(((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })())) == null ? '' : ((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()))).length === 0) && (dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()) === 'KRW'); } }, { id: "c_otherwise_98", fn: function(){ return (!((!(String(((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })())) == null ? '' : ((dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()))).length === 0) && (dma_corporationSummary.get("currIsoCd") ?? (() => { throw new Error("unresolved:" + "corporationSummary.currIsoCd"); })()) === 'KRW'))); } }, { id: "if_nfaithdisclsCorpHist_txt", fn: function(){ return ((dma_dircDisclsSysInfo.get("nfaithdisclsCorpHist") ?? (() => { throw new Error("unresolved:" + "dircDisclsSysInfo.nfaithdisclsCorpHist"); })()) === 'N'); } }, { id: "if_nfaithdisclsCorpHist_2_txt", fn: function(){ return ((dma_dircDisclsSysInfo.get("nfaithdisclsCorpHist") ?? (() => { throw new Error("unresolved:" + "dircDisclsSysInfo.nfaithdisclsCorpHist"); })()) === 'Y'); } }, { id: "if_spotIsuTrdMktTpCd_2", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '6' && (dma_session.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "session.company.listStatCd"); })()) === 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb13", fn: function () { return String(dma_corporationSummary.get("zipcd")) + " " + String(dma_corporationSummary.get("addr")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_DisclsPrfmDtl_onclick
 * @description 「상세보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_DisclsPrfmDtl_onclick = async function(e){
    try {
        await scwin.disclsPrfmDtl()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil20000.btn_DisclsPrfmDtl_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name viewNews
 * @description view News 처리
 * @param {String} divId divId
 * @returns {void}
 * @hidden N
 */
scwin.viewNews = function (divId) {
    if (scwin.conFormObj != null && scwin.conFormObj !== 'undefined') {
        scwin.conFormObj.style.display = 'none';
    }
    if ($c.util.getComponent(divId + '_divContn').getStyle('display') === 'none') {
        ($c.util.getComponent(divId + '_divContn') && $c.util.getComponent(divId + '_divContn').show ? $c.util.getComponent(divId + '_divContn').show() : console.warn('[sdd] show 대상 미해결: ' + divId + '_divContn'));
    } else {
        ($c.util.getComponent(divId + '_divContn') && $c.util.getComponent(divId + '_divContn').hide ? $c.util.getComponent(divId + '_divContn').hide() : console.warn('[sdd] hide 대상 미해결: ' + divId + '_divContn'));
    }
    scwin.conFormObj = $c.util.getComponent(divId + '_divContn');
};

/**
 * @method
 * @name disclsPrfmDtl
 * @description discls Prfm Dtl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.disclsPrfmDtl = async function () {
    const popUrl = '/ui/jsp/JLDFIL20010.xml';
    await $c.win.openPopup(popUrl, { id: "disclsPrfmPntDtl", scrollbars: false, resizable: false, width: "800", height: "690", type: "pageFramePopup" }, { method: "loadInitPageForDisclsPrfmPnt" });
};
